data.script:
const range = editor.getSelectedLineRange();
const text = editor.getTextInRange(range[0], range[1]);
if (!text.trim()) { context.fail('Select lines to change.'); }
else {
  const prompt = Prompt.create(); prompt.title = 'Append text to lines';
  prompt.addTextField('suffix', 'Text to append', ''); prompt.addButton('Append');
  if (!prompt.show()) { context.cancel(); }
  else {
    const suffix = prompt.fieldValues.suffix;
    if (suffix) {
      const newline = text.endsWith('\n');
      const lines = (newline ? text.slice(0, -1) : text).split('\n');
      editor.setTextInRange(range[0], range[1], lines.map(line => line + suffix).join('\n') + (newline ? '\n' : ''));
    }
  }
}
